WITH session_stats AS (SELECT session_id, COUNT(CASE WHEN event_type = 'page_view' THEN 1 END) AS page_view_count, ROUND(AVG(duration_sec), 2) AS avg_duration_sec FROM web_events WHERE session_id = 19 GROUP BY session_id) SELECT sessions.id, sessions.browser, sessions.device, session_stats.page_view_count, session_stats.avg_duration_sec FROM sessions LEFT JOIN session_stats ON sessions.id = session_stats.session_id WHERE session_stats.page_view_count > 4 ORDER BY session_stats.page_view_count
